import{_ as a,o as e,c as o,a2 as l}from"./chunks/framework.DnrXFDHb.js";const g=JSON.parse('{"title":"底模是什么","description":"说明 AI 绘画底模的作用、checkpoint 与 LoRA 的关系、模型兼容性判断方法和常见误区。","frontmatter":{"description":"说明 AI 绘画底模的作用、checkpoint 与 LoRA 的关系、模型兼容性判断方法和常见误区。"},"headers":[],"relativePath":"concepts/base-model.md","filePath":"concepts/base-model.md","lastUpdated":1788697768000}'),r={name:"concepts/base-model.md"};function i(s,t,n,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[l(`<h1 id="底模是什么" tabindex="-1">底模是什么 <a class="header-anchor" href="#底模是什么" aria-label="Permalink to &quot;底模是什么&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 底模（Base Model，常以 Checkpoint 文件形式出现）是 AI 绘画系统的核心生成模型，决定画面的默认风格、知识范围和能力上限；LoRA 等插件只能在这块“地基”上做加减，改变不了地基本身。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>读过 <a href="/llm/basics">大模型入门</a> 会更顺，知道模型是训练得到的产物即可——LLM 部分讲过“预训练给能力，微调教用法，对齐定边界”，底模就是绘画模型的地基：它决定整体的风格倾向与能力上限。<a href="/llm/training-alignment">训练、微调与对齐</a>提供微调与对齐的背景，同样不强制。</li><li>不要求安装过 ComfyUI 或 WebUI，本页只建立概念，工具选择在 <a href="/tools/common-tools">常用工具</a> 展开。</li><li>先接受一个边界：本页只讲底模的结构性差异（架构、分辨率、生态），不提供下载地址，也不回答“哪个模型最强”这类时效性问题。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>说明底模在文生图系统里处于什么位置，它决定什么、不决定什么。</li><li>区分底模、Checkpoint、Base Model 三个说法分别指什么。</li><li>解释为什么底模决定默认画风和能力上限，以及 U-Net 与 DiT 两代架构的分野。</li><li>用“地基与装修”的关系判断一个 LoRA 能不能配你的底模。</li><li>拿到一个新底模时，初步判断它属于哪个生态、能配什么插件。</li><li>用训练数据的视角，解释底模为什么画不出“没见过的概念”。</li><li>按“四看”清单给候选底模做第一轮筛选。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="底模、checkpoint、base-model-是什么关系" tabindex="-1">底模、Checkpoint、Base Model 是什么关系 <a class="header-anchor" href="#底模、checkpoint、base-model-是什么关系" aria-label="Permalink to &quot;底模、Checkpoint、Base Model 是什么关系&quot;">​</a></h3><p>在不同教程里你会看到三个相近的词：</p><ul><li><strong>底模</strong>：中文社区的习惯说法，指生成图片的核心模型。</li><li><strong>Checkpoint（检查点）</strong>：底模最常见的文件形式，通常是 <code>.safetensors</code> 或 <code>.ckpt</code>。训练过程中定期保存的模型状态也叫 checkpoint，公开发布时沿用了这个名字。</li><li><strong>Base Model（基座模型）</strong>：站在“训练或微调”角度的称呼。社区常说某个 LoRA 的 Base Model 是 SDXL，意思是它必须在 SDXL 这块地基上使用。</li></ul><p>日常说“换底模”，指的就是在工具里换一个 checkpoint 文件；说“这个 LoRA 适配什么底模”，指的就是它的 Base Model 标注。三个词指向同一个东西的不同侧面。</p><p>底模在整个系统中的位置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>底模（生成能力的来源）</span></span>
<span class="line"><span> ├─ 决定：默认画风、知识范围、分辨率习惯、生态兼容性</span></span>
<span class="line"><span> └─ 不决定：构图与姿势（ControlNet 管）、附加概念（LoRA 管）、完成度（步数与采样器管）</span></span></code></pre></div><h3 id="为什么底模决定画风的-底味" tabindex="-1">为什么底模决定画风的“底味” <a class="header-anchor" href="#为什么底模决定画风的-底味" aria-label="Permalink to &quot;为什么底模决定画风的“底味”&quot;">​</a></h3><p>底模是在海量“图文对”上训练出来的。它学会的不是某一张图，而是训练数据里反复出现的统计规律：人体比例、光影习惯、线条质感、常见题材。所谓画风，就是这些规律的分布偏向：</p><ul><li>训练数据以照片为主，输出就偏写实。</li><li>训练数据以插画、动漫截图为主，输出就偏二次元。</li><li>提示词的写法习惯也随之定型：有的生态偏自然语言长句，有的偏标签短句。</li><li>数据里某类题材过多或过少，模型就会对某些概念“偏科”。</li></ul><p>判断一个底模的画风倾向，最快的办法不是看参数表，而是三件事：看模型页示例图的风格是否一致；读模型卡对训练数据的说明；用同一句提示词在不同底模上做对比。注意示例图是作者挑过的，别把它当成模型的平均水平。</p><p>提示词只能引导底模在已有能力范围内偏移，不能凭空创造底模没学过的能力。一个偏写实的底模很难只靠提示词稳定变成纯动画截图风格，原因就在这里——缺的不是“引导”，而是整块能力。</p><h3 id="底模的-知识-有边界-没见过的概念画不像" tabindex="-1">底模的“知识”有边界：没见过的概念画不像 <a class="header-anchor" href="#底模的-知识-有边界-没见过的概念画不像" aria-label="Permalink to &quot;底模的“知识”有边界：没见过的概念画不像&quot;">​</a></h3><p>画风只是底模知识的一部分，另一半是具体概念：人物、服饰、建筑、物件。这部分知识同样来自训练数据，于是有一条容易被忽略的边界——底模的知识有截止时间（类似 LLM 的<a href="/glossary#knowledge-cutoff">知识截止</a>）：训练数据之后才出现的角色、产品与流行梗，它默认不认识。</p><p>把一个底模没见过的角色名写进提示词，通常不会报错，而是得到一张“形近拼接”的图：模型抓出训练数据里与这个词最相近的概念——相近的画风、相近的服饰、相近的脸型——拼出一个似是而非的结果。名字写得越具体，模型拼得越自信，但方向从一开始就偏了。</p><p>由此能解释几件常见怪事：</p><ul><li>老底模画不出新角色、新设备、新款服装：不是参数问题，是它压根没学过。</li><li>小众冷门的概念（某种传统服饰、某类冷门乐器）画得半生不熟：训练数据里相关样本太少，模型只学到模糊的平均印象。</li><li>同一个概念换个更通用的写法反而更准：通用词对应训练数据里更充足的样本。</li></ul><p>这条边界也是理解插件作用的前提。LoRA 能教底模认识一个小概念（某个角色、某种画风），但它本身要在匹配的底模上训练，从底模已有的相邻能力出发——底模完全没有地基的概念，插件同样起不来。补法与边界见 <a href="/lora/basics">LoRA 入门</a>，本页记成因：<strong>概念能不能画，先看底模的训练数据里有没有。</strong></p><h3 id="底模家族怎么分代-u-net-与-dit" tabindex="-1">底模家族怎么分代：U-Net 与 DiT <a class="header-anchor" href="#底模家族怎么分代-u-net-与-dit" aria-label="Permalink to &quot;底模家族怎么分代：U-Net 与 DiT&quot;">​</a></h3><p>Stable Diffusion 系列几代底模的差异，主要是结构性的：</p><ul><li><strong>SD1.5</strong>：最早普及的一代，采用 <strong>U-Net</strong>（一种以卷积为主的网络结构）做去噪，基础分辨率以 512 系为主。发布早、门槛低，围绕它积累的插件、教程和 LoRA 至今最庞大。</li><li><strong>SDXL</strong>：仍沿用 U-Net 架构但规模更大，基础分辨率升到 1024 系，画面结构和细节通常更好，生态成熟度很高。</li><li><strong>SD3 / SD3.5</strong>：SD3（2024 年 6 月）首次引入 <strong>MMDiT</strong>（DiT 类）架构，同年 10 月的 SD3.5 延续这一架构，是 SD 系从 U-Net 转向 DiT 类架构的一代；SD3.5 的社区许可对年收入低于 100 万美元的主体免费商用。</li><li><strong>FLUX、Qwen-Image、Z-Image 等新一代</strong>：转向 <strong>DiT（Diffusion Transformer，扩散 Transformer）</strong> 类架构，普遍对自然语言长句理解更好、质感更强；工作流和 LoRA 生态与 SD 系不直接通用。</li></ul><p>几代之间的结构关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SD1.5（U-Net，512 系分辨率）</span></span>
<span class="line"><span>SDXL（U-Net 加大，1024 系分辨率）</span></span>
<span class="line"><span> └─ Pony / Illustrious / NoobAI 等二次元向再训练分支</span></span>
<span class="line"><span>SD3 / SD3.5（MMDiT，DiT 类架构）</span></span>
<span class="line"><span>FLUX / Qwen-Image / Z-Image 等（DiT 类架构）</span></span></code></pre></div><p>同一生态内部还有变体，例如用于局部重绘的修补版、减少步数的蒸馏加速版（蒸馏：用大模型的输出训练一个更小模型的过程）。变体与主模型同属一个生态，插件兼容性通常保留，具体以发布说明为准。</p><p>架构换代的直接后果是生态不互通：LoRA、ControlNet 这类附件是针对特定底模的内部结构训练的，换一代底模就要换一套附件。所以选底模不只是选画质，也是在选一个生态。</p><h3 id="底模与-lora、controlnet-是什么关系" tabindex="-1">底模与 LoRA、ControlNet 是什么关系 <a class="header-anchor" href="#底模与-lora、controlnet-是什么关系" aria-label="Permalink to &quot;底模与 LoRA、ControlNet 是什么关系&quot;">​</a></h3><p>一个常用的类比：<strong>底模是地基，插件是装修</strong>。</p><ul><li><strong>LoRA</strong>：在底模权重上叠加的小幅修改，像装修里的刷墙、换家具——能明显改变观感，但动不了承重结构，而且装修方案是针对“这一栋房”设计的，换结构就对不上。</li><li><strong>ControlNet</strong>：从外部注入线稿、深度、骨架等约束，像施工图纸，管“画面长什么样”，不管“画风是什么”；细节见<a href="/concepts/controlnet">ControlNet 入门</a>。</li><li><strong>VAE</strong>：负责内部数据与人眼可见图片之间的转换，像门窗，属于基础设施（详见 <a href="/concepts/components">AI 绘画由哪些部分组成</a>）。</li></ul><p>装修的前提是房子盖好了。底模没学过的概念，插件和提示词都很难补上。</p><p>所以搭配的顺序是：先定底模，再选装修——顺序反了，往往两头别扭。</p><h3 id="选底模时看什么-四看清单" tabindex="-1">选底模时看什么：四看清单 <a class="header-anchor" href="#选底模时看什么-四看清单" aria-label="Permalink to &quot;选底模时看什么：四看清单&quot;">​</a></h3><p>知道了底模是什么，真正的难题往往是“下载哪一个”。本页不提供具体推荐（时效性内容归<a href="/models/ecosystems">常见模型生态</a>），但挑选的判断标准是稳定的，任何候选都可以过一遍这四看：</p><ol><li><strong>题材匹配</strong>：这个底模主要为哪类题材训练——写实照片、动漫插画还是平面设计？题材不对，画质再高也用不顺；判断画风倾向的办法见上文。</li><li><strong>代际与显存</strong>：新一代底模通常更大、更吃显存，先确认硬件带得动哪一代，再谈别的；老显卡上，生态成熟的中代底模常是更现实的选择。</li><li><strong>生态厚度</strong>：围绕它的 LoRA、ControlNet 模型与教程多不多，直接决定后续踩坑成本；附件与教程丰富的底模，遇到问题也搜得到答案。</li><li><strong>许可证</strong>：能不能商用、能不能公开发布作品，下载前看一眼；具体核对方法见<a href="/models/ecosystems">常见模型生态</a>。</li></ol><p>四看里最容易被低估的是生态厚度：一张示例图惊艳但社区冷清的底模，实际体验往往不如画质略逊、生态成熟的稳妥选项。</p><p>最后回应一个高频纠结：“先换底模，还是先练提示词？”看缺的是能力还是发挥。底模具备对应能力、只是描述不到位，先练提示词收益最大；要画的题材或风格根本不在底模知识范围内，提示词写得再好也只是让它往“最近的概念”上凑——此时该换底模或补概念插件。先判断能力缺不缺，再判断发挥好不好。</p><h2 id="最小推演-模型输出约等于底模底味加-lora-增量" tabindex="-1">最小推演：模型输出约等于底模底味加 LoRA 增量 <a class="header-anchor" href="#最小推演-模型输出约等于底模底味加-lora-增量" aria-label="Permalink to &quot;最小推演：模型输出约等于底模底味加 LoRA 增量&quot;">​</a></h2><p>把“画面在写实-动漫轴上的位置”简化成一个 0 到 100 的数字（0 纯写实，100 纯动漫）。假设三个底模底味不同，同一个角色 LoRA 提供固定 +20 的增量：</p><table tabindex="0"><thead><tr><th>底模</th><th style="text-align:right;">底味（写实-动漫轴）</th><th style="text-align:right;">加角色 LoRA（+20）后</th><th>说明</th></tr></thead><tbody><tr><td>A：偏写实</td><td style="text-align:right;">10</td><td style="text-align:right;">30</td><td>仍偏写实，LoRA 拉不动太多</td></tr><tr><td>B：均衡</td><td style="text-align:right;">50</td><td style="text-align:right;">70</td><td>偏移最明显，效果最可见</td></tr><tr><td>C：偏动漫</td><td style="text-align:right;">80</td><td style="text-align:right;">100（封顶）</td><td>底味已接近上限，LoRA 无处可加，甚至过冲</td></tr></tbody></table><p>推演步骤：</p><ol><li>LoRA 的影响是叠加在底模现状之上的增量，起点不同，同一个 LoRA 结果也不同。</li><li>底味已经到头的方向，LoRA 推不动，强行加大权重只会破坏画面。</li><li>所以“先选对底模、再上插件”通常比“用插件硬拗底模”可靠。</li><li>这也解释了为什么同一个 LoRA 在不同人手里效果差异很大：他们的底模底味本来就不一样。</li></ol><p>这个推演只说明“LoRA 的效果约等于底模底味加有限增量”这一直觉，不等于真实模型里存在一个可以读出的风格数值——真实的风格空间是高维的，LoRA 修改的方向也远比“加一个数”复杂。想验证真实效果，最直接的办法是用同一句提示词、固定 seed，在有和无 LoRA 之间做对照。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>文生图常见的四类模型文件经常被混着问，下表按“解决什么问题”区分（各部件在流程中的位置见 <a href="/concepts/components">AI 绘画由哪些部分组成</a>）：</p><table tabindex="0"><thead><tr><th>部件</th><th>它是什么</th><th>解决什么问题</th><th>什么时候用</th></tr></thead><tbody><tr><td>底模</td><td>完整的生成模型（checkpoint）</td><td>提供“会画什么”的全部基础能力</td><td>一次生成只加载一个</td></tr><tr><td>LoRA</td><td>底模之上的小型附加模型</td><td>补充角色、画风、服装等概念</td><td>挂在匹配的底模上，可叠加</td></tr><tr><td>VAE</td><td>潜空间与像素图的编解码器</td><td>把内部数据转换成人眼可见的图片</td><td>底模内置或单独指定</td></tr><tr><td>ControlNet</td><td>条件控制插件</td><td>用线稿、深度、骨架约束构图与姿势</td><td>构图不听话时</td></tr></tbody></table><p>一句话记忆：底模管“会画什么”，LoRA 管“多画一个概念”，VAE 管“怎么变成图片”，ControlNet 管“构图听谁的”。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“底模越新越好”</strong>：新架构不等于适合你。生态成熟度、显存要求、LoRA 与教程数量都是现实约束，换代期旧生态往往资源更全。</li><li><strong>“换个提示词就能换画风”</strong>：提示词只能在底模已有能力范围内引导。偏写实的底模很难只靠提示词稳定变成纯动漫风，反之亦然。</li><li><strong>“所有 <code>.safetensors</code> 文件都一样”</strong>：同一扩展名下可能是 checkpoint、LoRA、VAE、Embedding 或文本编码器，用途和大小量级完全不同，要按模型页说明判断。</li><li><strong>“底模决定一切，参数无所谓”</strong>：采样器、步数、CFG、分辨率同样明显影响成品；底模只定上限，不出成品。</li><li><strong>“名字像的底模就能混用插件”</strong>：不同大版本之间（例如 SD1.5 与 SDXL）默认不兼容，同一生态的新旧大版本也要以模型页的 Base Model 标注为准。</li><li><strong>“底模就是一个文件”</strong>：新一代模型常由底模、文本编码器、VAE 等多个文件组成，缺件会导致报错或效果异常。</li><li><strong>“底模认识所有知名角色”</strong>：底模的知识有截止时间，训练数据之后才出现的角色、产品与梗它并不知道；写名字只会得到“形近拼接”的结果，小众概念交给匹配底模上训练的 LoRA 或更新的底模。</li><li><strong>“换了底模，参数照旧”</strong>：每个底模有自己的推荐步数、CFG 与分辨率习惯，旧参数在新底模上可能明显走样；换底模后先读模型卡推荐值，重新固定 seed 建立基准。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-底模-checkpoint-base-model-三个词分别强调什么-日常说-换底模-是在换什么" tabindex="-1">1. “底模”“Checkpoint”“Base Model”三个词分别强调什么？日常说“换底模”是在换什么？ <a class="header-anchor" href="#_1-底模-checkpoint-base-model-三个词分别强调什么-日常说-换底模-是在换什么" aria-label="Permalink to &quot;1. “底模”“Checkpoint”“Base Model”三个词分别强调什么？日常说“换底模”是在换什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>底模是中文习惯说法，强调“核心生成模型”这个地位；Checkpoint 强调文件形式（通常是 <code>.safetensors</code> 或 <code>.ckpt</code>）；Base Model 站在训练角度，强调它是 LoRA 等附件所依赖的基础。日常说“换底模”，就是在工具里换一个 checkpoint 文件。</p></details><h3 id="_2-为什么偏写实的底模很难只靠提示词稳定变成动漫截图风" tabindex="-1">2. 为什么偏写实的底模很难只靠提示词稳定变成动漫截图风？ <a class="header-anchor" href="#_2-为什么偏写实的底模很难只靠提示词稳定变成动漫截图风" aria-label="Permalink to &quot;2. 为什么偏写实的底模很难只靠提示词稳定变成动漫截图风？&quot;">​</a></h3><details><summary>查看答案</summary><p>画风是训练数据分布的统计结果，已经写进整个模型的权重里。提示词只能在已有能力范围内引导偏移，提供不了底模没学过的完整动漫视觉规律；想稳定换风格，应该换底模，或在相近生态上用匹配的画风 LoRA 叠加。</p></details><h3 id="_3-为什么-sd1-5-的-lora-不能默认给-sdxl-用" tabindex="-1">3. 为什么 SD1.5 的 LoRA 不能默认给 SDXL 用？ <a class="header-anchor" href="#_3-为什么-sd1-5-的-lora-不能默认给-sdxl-用" aria-label="Permalink to &quot;3. 为什么 SD1.5 的 LoRA 不能默认给 SDXL 用？&quot;">​</a></h3><details><summary>查看答案</summary><p>LoRA 学到的是“如何修改某个底模内部权重的特定方向”，它与训练时那个底模的结构和权重分布绑定。SD1.5 与 SDXL 架构不同、权重完全不同，修改方向失去了作用对象，轻则无效，重则画面崩坏。选 LoRA 先看模型页的 Base Model 标注。</p></details><h3 id="_4-一个今年刚走红的动画角色-在去年发布的底模上怎么都画不像-问题出在哪" tabindex="-1">4. 一个今年刚走红的动画角色，在去年发布的底模上怎么都画不像，问题出在哪？ <a class="header-anchor" href="#_4-一个今年刚走红的动画角色-在去年发布的底模上怎么都画不像-问题出在哪" aria-label="Permalink to &quot;4. 一个今年刚走红的动画角色，在去年发布的底模上怎么都画不像，问题出在哪？&quot;">​</a></h3><details><summary>查看答案</summary><p>底模的知识来自训练数据，有截止时间：它默认不认识训练之后才出现的概念。角色名写进提示词，模型只会用训练数据里最相近的概念拼接一张“神似”的图。可行办法是换训练数据更新的底模，或找（乃至自己训练）匹配底模的这个角色的 LoRA。</p></details><h3 id="_5-先换底模还是先练提示词-应该怎么判断" tabindex="-1">5. “先换底模还是先练提示词”，应该怎么判断？ <a class="header-anchor" href="#_5-先换底模还是先练提示词-应该怎么判断" aria-label="Permalink to &quot;5. “先换底模还是先练提示词”，应该怎么判断？&quot;">​</a></h3><details><summary>查看答案</summary><p>看缺的是“能力”还是“发挥”。底模具备对应能力、只是描述不到位时，先练提示词收益最大；要画的题材或风格根本不在底模知识范围内时，提示词只能让它往最近的概念上凑，该换底模或用 LoRA 补概念。先判断能力缺不缺，再判断发挥好不好。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>前置概念：</strong> <a href="/ai/basics">AI 基础概念</a>解释模型、训练、推理与参数等共通知识。</li><li><strong>同主题：</strong> <a href="/concepts/components">AI 绘画由哪些部分组成</a>把底模放回完整文生图流水线。</li><li><strong>选择模型：</strong> <a href="/models/ecosystems">常见模型生态</a>帮助判断底模、附件与工具是否兼容。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2112.10752" target="_blank" rel="noreferrer">Stable Diffusion 论文</a>：Stable Diffusion 的原始论文，底模基本架构的出处。</li><li><a href="https://arxiv.org/abs/2307.01952" target="_blank" rel="noreferrer">SDXL 论文</a>：SDXL 相对前代结构性改进的官方论文。</li><li><a href="https://github.com/black-forest-labs/flux" target="_blank" rel="noreferrer">FLUX 官方仓库</a>：Black Forest Labs 的 FLUX.1 系列官方代码与说明。</li><li><a href="https://github.com/black-forest-labs/flux2" target="_blank" rel="noreferrer">FLUX.2 官方仓库</a>：FLUX.2 的官方推理仓库。</li><li><a href="https://huggingface.co/docs/diffusers/index" target="_blank" rel="noreferrer">Hugging Face Diffusers 文档</a>：各代 Stable Diffusion 模型结构与用法的官方文档。</li><li><a href="https://stability.ai" target="_blank" rel="noreferrer">Stability AI 官网</a>：Stable Diffusion 系列主要发布方之一，模型发布与技术说明的第一手来源。</li><li><a href="https://github.com/QwenLM/Qwen-Image" target="_blank" rel="noreferrer">Qwen-Image 官方仓库</a>：Qwen-Image 的官方代码与模型说明。</li></ul>`,69)])])}const u=a(r,[["render",i]]);export{g as __pageData,u as default};
